from produire import produire,paras,table,steps
from medicaments import ciproxin_hc
parts=[
('L’otite externe aiguë bactérienne est une infection inflammatoire de la peau du conduit. Les {limites du diagnostic} la distinguent d’une otite moyenne qui s’écoule à travers le tympan. Une douleur au tragus renforce l’orientation externe.',paras('L’épisode survient rapidement avec douleur, prurit ou sensation d’oreille pleine et signes d’inflammation du conduit. L’otorrhée est possible mais non obligatoire.', 'Une otite externe peut coexister avec une perforation ou une maladie moyenne. L’origine bactérienne n’est pas déduite de la seule couleur des sécrétions.')),
('Humidité et microtraumatismes favorisent l’infection. Les {terrains à reconnaître} modifient le risque de complication. L’âge seul ne permet pas de décider du traitement.',paras('Baignade, nettoyage agressif, coton-tige et grattage altèrent la protection cutanée. Appareils et bouchons peuvent retenir l’humidité ou irriter la peau.', 'Diabète, immunodépression, radiothérapie locale ou antécédent opératoire demandent davantage de vigilance. Une présentation simple chez un sujet sain ne se gère pas comme une douleur profonde persistante chez un sujet à risque.')),
('La {rupture de la barrière cutanée} favorise la prolifération bactérienne. Œdème et débris peuvent gêner l’audition et la pénétration des gouttes. Une infection profonde sort du cadre d’une otite externe simple.',paras('Le cérumen et la migration de l’épithélium participent à la protection du conduit. L’humidité prolongée, une dermatose ou un traumatisme créent une porte d’entrée.', 'Pseudomonas aeruginosa et Staphylococcus aureus font partie des bactéries habituelles. Leur fréquence dépend du contexte et ne justifie pas un pourcentage suisse supposé.', 'L’œdème dans un conduit étroit peut rendre la douleur intense. Une extension aux tissus voisins, à l’os ou aux nerfs impose une autre stratégie.')),
('Les {situations urgentes} doivent être distinguées d’une inflammation locale. Une douleur nocturne disproportionnée ou un déficit facial fait craindre une otite nécrosante. Une extension rapide ou une altération générale impose une évaluation urgente.',paras('Chercher diabète ou immunodépression, douleur profonde résistante, granulations et atteinte d’un nerf crânien. L’absence de fièvre ne permet pas d’exclure une infection invasive.', 'Rechercher aussi tuméfaction rétroauriculaire, pavillon décollé, vertige important ou baisse auditive soudaine. Ces signes ne sont pas expliqués par défaut par une otite externe banale.')),
('L’{anamnèse ciblée} précise les expositions et traitements. Elle recherche douleur, prurit, durée et évolution. Un antécédent de perforation change immédiatement les choix locaux.',paras('Demander baignade, grattage, coton-tige, appareil auditif, embout ou produit introduit. Identifier les gouttes utilisées, leur durée et l’effet obtenu.', 'Rechercher maladie cutanée, allergie, drain, chirurgie, diabète et immunodépression. Noter une baisse auditive, un vertige, une douleur nocturne ou une extension au visage.')),
('L’{examen du conduit et du tympan} est central. La douleur provoquée et l’inflammation externe soutiennent le diagnostic. Si le tympan reste invisible, son intégrité demeure incertaine.',paras('Examiner pavillon, tragus, peau adjacente et mastoïde. À l’otoscopie prudente, noter œdème, rougeur, débris, pus, granulation ou corps étranger.', 'Un nettoyage ou une aspiration sous contrôle peut être nécessaire pour voir le tympan et permettre le traitement. Éviter toute irrigation à l’aveugle et demander une aide spécialisée si nécessaire.', 'Évaluer l’audition et la motricité faciale selon la présentation. Une lésion focale persistante ou une masse nécessite un bilan.')),
('Les {principales alternatives} changent le traitement. Prurit persistant et débris fongiques suggèrent une mycose. Écoulement chronique et tympan anormal font rechercher une atteinte moyenne.',table(['Alternative','Indice'],[['Otite moyenne perforée.','Otalgie aiguë précédant le pus et perforation.'],['Otomycose.','Prurit et débris évocateurs, parfois après antibiotiques.'],['Dermatite ou allergie de contact.','Desquamation, suintement, lien avec un produit.'],['Corps étranger.','Objet visible ou écoulement unilatéral inexpliqué.'],['Cholestéatome.','Récidive, rétraction, kératine ou polype.'],['Otite nécrosante.','Douleur profonde persistante, terrain à risque, granulations.']])) ,
('Le diagnostic est principalement clinique. Les {éléments positifs} associent symptômes récents et signes d’inflammation du conduit. Une simple rougeur tympanique ne suffit pas à conclure à une otite moyenne.',paras('Douleur ou prurit de début rapide, sensibilité au tragus ou au pavillon, œdème ou érythème du conduit forment un ensemble cohérent. L’écoulement et la baisse auditive peuvent s’y associer.', 'Vérifier le tympan lorsque cela est possible. Reconsidérer le diagnostic si l’évolution n’est pas celle attendue ou si l’examen révèle des signes de complication.')),
('Le {bilan complémentaire} dépend de l’évolution et du traitement envisagé. Une imagerie n’est pas habituelle dans une forme simple. Une suspicion d’infection invasive impose un bilan spécialisé.',paras('Un prélèvement devient particulièrement utile en cas d’échec, récidive, terrain à risque ou suspicion fongique. Pour Ciproxin HC, l’information professionnelle suisse demande un test de sensibilité avant le début du traitement.', 'Une culture positive doit être interprétée avec la clinique. En cas de suspicion d’otite nécrosante, l’ORL organise prélèvements, bilan biologique et imagerie ; ne pas attendre ces résultats pour demander l’avis urgent.')),
('L’{enchaînement des décisions} associe gravité, visibilité et traitement adapté. La qualité de l’administration influence l’efficacité. L’absence de réponse conduit à réexaminer plutôt qu’à prolonger automatiquement.',steps('Écarter infection invasive, extension importante, traumatisme et autre urgence.', 'Évaluer conduit et tympan ; lever les obstacles au traitement par nettoyage professionnel ou mèche si indiqué.', 'Choisir une préparation adaptée à l’indication, au tympan, à l’âge et aux contre-indications ; traiter la douleur.', 'Expliquer administration et protection de l’oreille ; réévaluer si pas d’amélioration en 48 à 72 heures, plus tôt si aggravation.', 'À l’échec, vérifier observance, pénétration, mycose, allergie, résistance, corps étranger ou maladie moyenne ; demander avis ORL selon situation.')),
('Le traitement est habituellement local dans une forme bactérienne non compliquée. Les {modalités suisses} dépendent de la préparation exacte. Des antibiotiques systémiques ne sont pas indiqués de routine.',paras('@@MEDICAMENTS@@')+paras('Ciproxin HC ne doit pas être utilisé sur un tympan perforé ou possiblement perforé. Le schéma suisse est de trois gouttes deux fois par jour pendant sept jours dès deux ans, dans les limites de l’information professionnelle citée.', 'En cas de perforation, l’ORL et le pharmacien doivent choisir une préparation non ototoxique adaptée. Ne pas substituer automatiquement Ciloxan : son information suisse est ophtalmique et l’usage auriculaire est hors information professionnelle.', 'Associer une antalgie adaptée à l’âge, au terrain et aux contre-indications. Une extension hors du conduit, une immunodépression ou une infection sévère peut nécessiter un traitement systémique ; l’otite nécrosante relève d’une filière spécialisée.')),
('La {prévention des récidives} protège la peau du conduit. Elle limite eau stagnante et traumatismes. Les produits instillés sans avis peuvent entretenir irritation ou allergie.',paras('Éviter cotons-tiges et grattage. Garder l’oreille à l’abri de l’eau durant l’épisode selon les consignes reçues ; ne pas introduire de liquide domestique ou de produit alcoolisé en cas de tympan incertain.', 'Entretenir les dispositifs auditifs et rechercher une dermatose ou une allergie lors d’épisodes répétés. Expliquer quand revenir sans attendre la consultation prévue.')),
('L’otite externe simple est un diagnostic clinique. Le tympan conditionne la sécurité des gouttes. Ciproxin HC a des limites suisses précises. Douleur disproportionnée et échec à 48 à 72 heures imposent une réévaluation.','')]
quiz=[('L’otorrhée est-elle obligatoire ?','Non : douleur, prurit et inflammation du conduit peuvent suffire à orienter.'),('Que suggère une douleur au tragus ?','Une atteinte du conduit externe, à confronter à l’examen.'),('Un tympan invisible est-il intact par défaut ?','Non : son intégrité reste incertaine.'),('Une irrigation à l’aveugle est-elle adaptée ?','Non : elle expose à une complication si le tympan est ouvert.'),('Quel terrain renforce le risque d’otite nécrosante ?','Notamment diabète ou immunodépression.'),('La fièvre est-elle nécessaire pour suspecter une forme invasive ?','Non : douleur profonde disproportionnée et autres signes doivent alerter.'),('Les antibiotiques oraux sont-ils systématiques ?','Non : le traitement est généralement local dans une forme simple.'),('Ciproxin HC contient-il seulement un antibiotique ?','Non : il associe ciprofloxacine et hydrocortisone.'),('Quelle est sa dose AIPS dès deux ans ?','Trois gouttes deux fois par jour pendant sept jours, selon indication et contre-indications.'),('Peut-on l’utiliser si une perforation est suspectée ?','Non : cette situation est explicitement contre-indiquée.'),('L’information suisse prévoit-elle un test de sensibilité ?','Oui, avant le début du traitement par Ciproxin HC.'),('Le même schéma est-il établi chez les moins de deux ans ?','Non : ne pas extrapoler la posologie citée.'),('Peut-on ignorer grossesse et allaitement parce que les gouttes sont locales ?','Non : l’AIPS limite l’utilisation aux cas d’absolue nécessité.'),('Que faire sans amélioration en 48 à 72 heures ?','Réexaminer diagnostic, administration et complications ; adapter la prise en charge.')]
produire(1,parts,quiz,(1,3,7,11,13,14,15),ciproxin_hc)
